import { apiClient, unwrap, type BffResponse } from '@linm-soft-org/linm-web-common-components';

export type VoucherCodeFormatDto = {
  id: string;
  codeType: string;
  prefix: string;
  description: string;
  format: string;
  isActive: boolean;
};

const BASE = '/system';

export const voucherCodeFormatEndpoint = {
  getList: async (): Promise<VoucherCodeFormatDto[]> => {
    const res = await apiClient.get<BffResponse<VoucherCodeFormatDto[]>>(`${BASE}/voucher-code-formats`);
    return unwrap(res) ?? [];
  },
};
