import React from 'react';
import { InAppLink } from '../../router/InAppLink';
import {
  companyService,
  getActiveCompanyId,
  setActiveCompanyId,
  useAppToast,
  useNavTitle,
  type ActiveCompanyItem,
} from '@linm-soft-org/linm-web-common-components';
import { Button } from '../../ui';
import {
  jobsService,
  type PosBillOpsActionResult,
  type PosBillOpsPreview,
} from '../../services/jobs';
import styles from './PosBillOpsPage.module.css';

const fmtMoney = (n: number) => `${n.toLocaleString('vi-VN')} ₫`;

const PosBillOpsPage: React.FC = () => {
  useNavTitle('Thao tác HĐ POS theo billId');
  const toast = useAppToast();

  const [companies, setCompanies] = React.useState<ActiveCompanyItem[]>([]);
  const [companyCode, setCompanyCode] = React.useState('');
  const [billIdInput, setBillIdInput] = React.useState('');
  const [previewOnly, setPreviewOnly] = React.useState(true);
  const [preview, setPreview] = React.useState<PosBillOpsPreview | null>(null);
  const [lastResult, setLastResult] = React.useState<PosBillOpsActionResult | null>(null);
  const [loadingPreview, setLoadingPreview] = React.useState(false);
  const [runningAction, setRunningAction] = React.useState<string | null>(null);
  const [activeTab, setActiveTab] = React.useState<'summary' | 'fm' | 'erp' | 'mappings'>('summary');

  React.useEffect(() => {
    companyService
      .getActiveList()
      .then((list) => {
        setCompanies(list);
        const active = getActiveCompanyId();
        const match = list.find((c) => c.id === active);
        const initial = match?.id ?? list[0]?.id ?? '';
        if (initial) {
          setCompanyCode(initial);
          setActiveCompanyId(initial);
        }
      })
      .catch((e: Error) => toast.error(e.message));
  }, [toast]);

  const parsedBillId = React.useMemo(() => {
    const raw = billIdInput.replace(/,/g, '').trim();
    const n = Number(raw);
    return Number.isFinite(n) && n > 0 ? n : null;
  }, [billIdInput]);

  const applyTenant = React.useCallback((code: string) => {
    const trimmed = code.trim();
    setCompanyCode(trimmed);
    if (trimmed) setActiveCompanyId(trimmed);
  }, []);

  const loadPreview = React.useCallback(() => {
    if (!companyCode.trim()) {
      toast.warning('Chọn đơn vị cơ sở trước.');
      return;
    }
    if (!parsedBillId) {
      toast.warning('Nhập billId hợp lệ (số nguyên > 0).');
      return;
    }
    setActiveCompanyId(companyCode.trim());
    setLoadingPreview(true);
    setLastResult(null);
    jobsService
      .getPosBillOpsPreview(parsedBillId)
      .then((data) => {
        setPreview(data);
        setActiveTab('summary');
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoadingPreview(false));
  }, [companyCode, parsedBillId, toast]);

  const runAction = React.useCallback(
    (action: 'resync' | 'repost' | 'refill-vat') => {
      if (!companyCode.trim() || !parsedBillId) {
        toast.warning('Chọn đơn vị và nhập billId.');
        return;
      }
      const labels = {
        resync: 'Resync FM → ERP',
        repost: 'Ghi sổ (re-post)',
        'refill-vat': 'Re-fill VAT',
      };
      if (!previewOnly && !window.confirm(`${labels[action]} billId ${parsedBillId}?`)) return;

      setActiveCompanyId(companyCode.trim());
      setRunningAction(action);
      const body = { billId: parsedBillId, dryRun: previewOnly };
      const call =
        action === 'resync'
          ? jobsService.posBillOpsResync(body)
          : action === 'repost'
            ? jobsService.posBillOpsRepost(body)
            : jobsService.posBillOpsRefillVat(body);

      call
        .then((result) => {
          setLastResult(result);
          if (result.success) toast.success(result.message);
          else toast.error(result.message);
          if (!previewOnly) loadPreview();
        })
        .catch((e: Error) => toast.error(e.message))
        .finally(() => setRunningAction(null));
    },
    [companyCode, parsedBillId, previewOnly, toast, loadPreview],
  );

  return (
    <div className={styles.page} data-testid="pos-bill-ops-page">
      <p className={styles.breadcrumb}>
        <InAppLink to="/admin/jobs">Job hub</InAppLink>
        {' · '}
        <InAppLink to="/admin/jobs/external-runs">Theo dõi sync REVA</InAppLink>
      </p>

      <h1 className={styles.title}>Thao tác HĐ POS theo billId</h1>
      <p className={styles.sub}>
        Preview convert FM ↔ ERP · Resync · Ghi sổ · Re-fill VAT — một phiếu tại một thời điểm.
      </p>

      <section className={styles.panel} data-testid="pos-bill-ops-form">
        <div className={styles.toolbarRow}>
          <label>
            Đơn vị
            <select
              value={companyCode}
              onChange={(e) => applyTenant(e.target.value)}
              data-testid="pos-bill-ops-company"
            >
              <option value="">— chọn —</option>
              {companies.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.id} — {c.name}
                </option>
              ))}
            </select>
          </label>

          <label>
            Bill ID (Số HĐ POS)
            <input
              type="text"
              inputMode="numeric"
              placeholder="vd. 1388219"
              value={billIdInput}
              onChange={(e) => setBillIdInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && loadPreview()}
              data-testid="pos-bill-ops-bill-id"
            />
          </label>

          <label className={styles.checkboxLabel}>
            <input
              type="checkbox"
              checked={previewOnly}
              onChange={(e) => setPreviewOnly(e.target.checked)}
              data-testid="pos-bill-ops-preview-only"
            />
            Chế độ preview (dry-run — không ghi DB)
          </label>
        </div>

        <div className={styles.toolbarRow}>
          <Button
            type="button"
            onClick={loadPreview}
            disabled={loadingPreview || !parsedBillId}
            data-testid="pos-bill-ops-load-preview"
          >
            {loadingPreview ? 'Đang tải…' : 'Xem preview'}
          </Button>
          <Button
            type="button"
            variant="secondary"
            onClick={() => runAction('resync')}
            disabled={Boolean(runningAction) || !parsedBillId}
            data-testid="pos-bill-ops-resync"
          >
            {runningAction === 'resync' ? 'Đang chạy…' : 'Resync'}
          </Button>
          <Button
            type="button"
            variant="secondary"
            onClick={() => runAction('repost')}
            disabled={Boolean(runningAction) || !parsedBillId}
            data-testid="pos-bill-ops-repost"
          >
            {runningAction === 'repost' ? 'Đang chạy…' : 'Re-post'}
          </Button>
          <Button
            type="button"
            variant="secondary"
            onClick={() => runAction('refill-vat')}
            disabled={Boolean(runningAction) || !parsedBillId}
            data-testid="pos-bill-ops-refill-vat"
          >
            {runningAction === 'refill-vat' ? 'Đang chạy…' : 'Re-fill VAT'}
          </Button>
        </div>
      </section>

      {preview && (
        <section className={styles.panel} data-testid="pos-bill-ops-preview-panel">
          <h2>
            Preview — {preview.legacyCode}
            {preview.canImport ? (
              <span className={styles.badgeOk}> Sẵn sàng import</span>
            ) : (
              <span className={styles.badgeWarn}> Chưa import được</span>
            )}
          </h2>

          <div className={styles.tabRow}>
            {(['summary', 'fm', 'erp', 'mappings'] as const).map((tab) => (
              <button
                key={tab}
                type="button"
                className={activeTab === tab ? styles.tabActive : styles.tab}
                onClick={() => setActiveTab(tab)}
              >
                {tab === 'summary' && 'Tóm tắt'}
                {tab === 'fm' && 'FM source'}
                {tab === 'erp' && 'ERP preview'}
                {tab === 'mappings' && `Mapping (${preview.fieldMappings.length})`}
              </button>
            ))}
          </div>

          {activeTab === 'summary' && (
            <div className={styles.previewGrid}>
              <div>
                <strong>FM</strong>: {preview.fmFound ? 'Có chi tiết' : 'Không tìm thấy'}
              </div>
              <div>
                <strong>ERP HĐ</strong>:{' '}
                {preview.erpInvoice ? (
                  <>
                    <a href={preview.erpInvoice.viewPath} target="_blank" rel="noreferrer">
                      {preview.erpInvoice.code}
                    </a>
                    {' · '}
                    {fmtMoney(preview.erpInvoice.totalAmount)} · XL {preview.erpInvoice.processingLevel} ·{' '}
                    {preview.erpInvoice.status}
                  </>
                ) : (
                  'Chưa có — cần Resync'
                )}
              </div>
              <div>
                <strong>PT liên kết</strong>: {preview.linkedReceipts.length}
                {preview.linkedReceipts.length > 0 && (
                  <ul>
                    {preview.linkedReceipts.map((r) => (
                      <li key={r.id}>
                        <a href={r.viewPath} target="_blank" rel="noreferrer">
                          {r.code}
                        </a>
                        {' — '}
                        {fmtMoney(r.amount)} · {r.status}
                      </li>
                    ))}
                  </ul>
                )}
              </div>
              {preview.warnings.length > 0 && (
                <div className={styles.warnBox}>
                  <strong>Cảnh báo</strong>
                  <ul>
                    {preview.warnings.map((w) => (
                      <li key={w}>{w}</li>
                    ))}
                  </ul>
                </div>
              )}
              {preview.errors.length > 0 && (
                <div className={styles.errorBox}>
                  <strong>Lỗi</strong>
                  <ul>
                    {preview.errors.map((e) => (
                      <li key={e}>{e}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}

          {activeTab === 'fm' && (
            <pre className={styles.jsonBlock}>{preview.fmSourceJson ?? '—'}</pre>
          )}
          {activeTab === 'erp' && (
            <pre className={styles.jsonBlock}>{preview.erpPreviewJson ?? '—'}</pre>
          )}
          {activeTab === 'mappings' && (
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>FM</th>
                  <th>ERP</th>
                  <th>Status</th>
                  <th>Ghi chú</th>
                </tr>
              </thead>
              <tbody>
                {preview.fieldMappings.map((m, i) => (
                  <tr key={`${m.fmField}-${m.erpField}-${i}`}>
                    <td>{m.fmField}</td>
                    <td>{m.erpField}</td>
                    <td>{m.status}</td>
                    <td>{m.note ?? ''}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>
      )}

      {lastResult && (
        <section className={styles.panel} data-testid="pos-bill-ops-result-panel">
          <h2>Kết quả action — {lastResult.success ? 'OK' : 'Lỗi'}</h2>
          <p>{lastResult.message}</p>
          {lastResult.voucherCodes.length > 0 && (
            <p>
              Chứng từ: <code>{lastResult.voucherCodes.join(', ')}</code>
            </p>
          )}
          {lastResult.postPlan.length > 0 && (
            <>
              <p>Ghi sổ dự kiến ({lastResult.postPlan.length}):</p>
              <ul>
                {lastResult.postPlan.map((p) => (
                  <li key={p.id}>
                    {p.documentType} · {p.code} — {p.reason}
                  </li>
                ))}
              </ul>
            </>
          )}
          {lastResult.warnings.map((w) => (
            <p key={w} className={styles.warnText}>
              {w}
            </p>
          ))}
          {lastResult.errors.map((e) => (
            <p key={e} className={styles.errorText}>
              {e}
            </p>
          ))}
        </section>
      )}
    </div>
  );
};

export default PosBillOpsPage;
