import React from 'react';
import {
  EXTERNAL_SYNC_AUTO_REFRESH_MAX_SECONDS,
  EXTERNAL_SYNC_AUTO_REFRESH_MIN_SECONDS,
  clampIntervalSeconds,
  type ExternalSyncAutoRefreshSettings,
} from './externalSyncAutoRefreshSettings';

const panelStyle: React.CSSProperties = {
  marginBottom: 16,
  padding: '12px 16px',
  border: '1px solid #e2e8f0',
  borderRadius: 8,
  background: '#f8fafc',
};

const rowStyle: React.CSSProperties = {
  display: 'flex',
  flexWrap: 'wrap',
  gap: 16,
  alignItems: 'flex-end',
  marginTop: 10,
};

const labelStyle: React.CSSProperties = {
  display: 'flex',
  gap: 8,
  alignItems: 'flex-start',
  fontSize: 13,
  maxWidth: 420,
  cursor: 'pointer',
};

const inputStyle: React.CSSProperties = {
  width: 88,
  padding: '4px 8px',
  borderRadius: 4,
  border: '1px solid #cbd5e1',
  fontSize: 13,
};

export type ExternalSyncAutoRefreshPanelProps = {
  settings: ExternalSyncAutoRefreshSettings;
  onChange: (next: ExternalSyncAutoRefreshSettings) => void;
};

const ExternalSyncAutoRefreshPanel: React.FC<ExternalSyncAutoRefreshPanelProps> = ({
  settings,
  onChange,
}) => {
  const [draftSeconds, setDraftSeconds] = React.useState(String(settings.intervalSeconds));

  React.useEffect(() => {
    setDraftSeconds(String(settings.intervalSeconds));
  }, [settings.intervalSeconds]);

  const commitInterval = React.useCallback(() => {
    const parsed = Number.parseInt(draftSeconds, 10);
    onChange({
      ...settings,
      intervalSeconds: clampIntervalSeconds(parsed),
    });
  }, [draftSeconds, onChange, settings]);

  return (
    <div style={panelStyle} data-testid="external-sync-auto-refresh-panel">
      <strong>Tự làm mới trang theo dõi</strong>
      <p style={{ margin: '4px 0 0', color: '#64748b', fontSize: 13 }}>
        Giảm tần suất poll khi run đang chạy để tránh spam API. Cấu hình lưu trên trình duyệt.
      </p>
      <div style={rowStyle}>
        <label style={labelStyle}>
          <input
            type="checkbox"
            checked={settings.enabled}
            data-testid="external-sync-auto-refresh-enabled"
            onChange={(e) => onChange({ ...settings, enabled: e.target.checked })}
          />
          <span>
            <strong>Bật tự làm mới khi run đang chạy</strong>
            <br />
            <span style={{ color: '#64748b' }}>
              Tắt để chỉ làm mới thủ công (nút Làm mới trên danh sách run / checkpoint).
            </span>
          </span>
        </label>
        <label style={{ fontSize: 13, display: 'flex', flexDirection: 'column', gap: 4 }}>
          <span>Chu kỳ làm mới (giây)</span>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <input
              type="number"
              min={EXTERNAL_SYNC_AUTO_REFRESH_MIN_SECONDS}
              max={EXTERNAL_SYNC_AUTO_REFRESH_MAX_SECONDS}
              step={1}
              value={draftSeconds}
              disabled={!settings.enabled}
              style={inputStyle}
              data-testid="external-sync-auto-refresh-interval"
              onChange={(e) => setDraftSeconds(e.target.value)}
              onBlur={commitInterval}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  commitInterval();
                }
              }}
            />
            <span style={{ color: '#64748b' }}>
              {EXTERNAL_SYNC_AUTO_REFRESH_MIN_SECONDS}–{EXTERNAL_SYNC_AUTO_REFRESH_MAX_SECONDS}s
            </span>
          </div>
        </label>
      </div>
    </div>
  );
};

export default ExternalSyncAutoRefreshPanel;
